    "name",
    "description",
    "instructions",
    "first_message",
    "ai_provider_connector_id",
    "skill_access_config",
    "max_tokens",
    "depends_on",
    "run_as",
    "jwt_authentication",
    "conversation_idle_timeout",
    "a2a_streaming",
    "a2a_create_record_enabled",
    "type",
    "bedrock_agent_arn",
    "starting_actions",
