            // its provider — the provider's own data block carries the name.
            // Deriving providerKey/modelKey this way (not by splitting the
            // connector's combined tfLabel) is the same derivation
            // renderAiProvidersBag uses, so the printed token matches the catalog.
            const identity = connectorIdentityFromTf(connectorAttr.type, connectorAttr.label, ctx);
            if (identity.catalogKey === undefined) {
                ctx.diagnostics.push(`${where}: references data.${connectorAttr.type}.${connectorAttr.label} but the stream has no model_name/provider for it; dropped`);
            }
